-- composition of rule kernels GroupByOrder x OmitOrderBy (sqlite), template scalar_filter
SELECT count(*) FROM (WITH cte1 AS (SELECT DISTINCT 7 AS c0 FROM tp AS a1 ORDER BY 1) SELECT CAST('ß' AS TEXT) AS c0, CAST(10.0 AS REAL) AS c1, '{"k": -1, "a": [1, 2, 3]}' AS c2 UNION SELECT a2.c1 AS c0, CASE WHEN FALSE THEN CAST(10.0 AS REAL) ELSE CAST(1.0 AS REAL) END AS c1, (SELECT JSON_GROUP_ARRAY (7 ORDER BY 7) FROM cte1 AS a3 WHERE FALSE) AS c2 FROM tl AS a2 WHERE ('{"k": 1, "a": [1, 2]}' = '{}')) AS ka WHERE (SELECT count(*) FROM (SELECT CAST('abc' AS TEXT) AS c0, 500 AS c1, '2024-02-29' AS c2 UNION SELECT a1.c2 AS c0, a1.c1 AS c1, '2024-12-31' AS c2 FROM (SELECT '1970-01-01' AS c0, 21 AS c1, CAST('{"k": 1}' AS TEXT) AS c2 ORDER BY 2, 3) AS a1 GROUP BY a1.c1, a1.c2) AS kb) >= 0;
